// HasBlockedGroups applies the HasEdge predicate on the "blocked_groups" edge.
func HasBlockedGroups() predicate.TrustCenterNDARequestSetting {
	return predicate.TrustCenterNDARequestSetting(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, BlockedGroupsTable, BlockedGroupsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBlockedGroupsWith applies the HasEdge predicate on the "blocked_groups" edge with a given conditions (other predicates).
func HasBlockedGroupsWith(preds ...predicate.Group) predicate.TrustCenterNDARequestSetting {
	return predicate.TrustCenterNDARequestSetting(func(s *sql.Selector) {
		step := newBlockedGroupsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

